  "characters[char-aot-petra].name": "Petra Ral",
  "characters[char-aot-oluo].name": "Oluo Bozado",
  "characters[char-aot-eld].name": "Eld Jinn",
  "characters[char-aot-gunther].name": "Gunther Schultz",
  "characters[char-aot-ilse].name": "Ilse Langnar",
  "characters[char-aot-nifa].name": "Nifa",
  "characters[char-aot-shadis].name": "Keith Shadis",
  "characters[char-aot-hannes].name": "Hannes",
  "characters[char-aot-pixis].name": "Dot Pixis",
  "characters[char-aot-rico].name": "Rico Brzenska",
